export function ContactPage() {
  const { lang } = useSite();
  const [submitted, setSubmitted] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const labels = { name: { "zh-TW": "姓名", "zh-CN": "姓名", en: "Name" }, company: { "zh-TW": "公司名稱", "zh-CN": "公司名称", en: "Company" }, email: { "zh-TW": "工作 Email", "zh-CN": "工作 Email", en: "Work email" }, need: { "zh-TW": "需求類型", "zh-CN": "需求类型", en: "What can we help with?" }, message: { "zh-TW": "想先聊什麼？", "zh-CN": "想先聊什么？", en: "What would you like to discuss?" } };
  const required = lang === "en" ? "Please complete this field" : lang === "zh-CN" ? "请完成此字段" : "請完成此欄位";
  const emailError = lang === "en" ? "Enter a valid work email" : lang === "zh-CN" ? "请输入有效的工作 Email" : "請輸入有效的工作 Email";
  const handleSubmit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); const data = new FormData(event.currentTarget); const nextErrors: Record<string, string> = {}; ["name", "company", "email", "need", "message"].forEach((key) => { if (!String(data.get(key) || "").trim()) nextErrors[key] = required; }); const email = String(data.get("email") || ""); if (email && !/^\S+@\S+\.\S+$/.test(email)) nextErrors.email = emailError; setErrors(nextErrors); if (Object.keys(nextErrors).length === 0) { setSubmitted(true); event.currentTarget.reset(); } };
  return <><Meta title={lang === "en" ? "Contact Eryndex" : lang === "zh-CN" ? "联系 Eryndex" : "聯絡 Eryndex"} description={lang === "en" ? "Book a Eryndex product demo or start a conversation about your operational needs" : "預約 Eryndex 產品展示，與我們討論企業營運需求"} /><PageHeader index="05" eyebrow={{ "zh-TW": "聯絡我們", "zh-CN": "联系我们", en: "Contact" }} title={lang === "en" ? <>Bring us the<br /><em>work behind the work</em></> : lang === "zh-CN" ? <>把工作背后的<br /><em>问题带来</em></> : <>把工作背後的<br /><em>問題帶來</em></>} intro={{ "zh-TW": "告訴我們目前最想釐清的工作場景，我們會從需求、資料環境與導入節奏開始討論", "zh-CN": "告诉我们目前最想厘清的工作场景，我们会从需求、数据环境与导入节奏开始讨论", en: "Tell us about the work scenario you want to clarify. We will start with your needs, data environment, and pace of adoption" }} /><section className="contact-section section-dark"><div className="container contact-grid"><div className="contact-aside"><Eyebrow>{lang === "en" ? "Start a conversation" : lang === "zh-CN" ? "开始对话" : "開始對話"}</Eyebrow><h2>{lang === "en" ? "No pitch deck required" : lang === "zh-CN" ? "不需要准备提案简报" : "不需要準備提案簡報"}</h2><p>{lang === "en" ? "A useful first conversation can begin with one repetitive task, one unclear risk, or one question you keep asking in meetings" : lang === "zh-CN" ? "一次有用的对话，可以从一个重复任务、一个不清晰的风险，或一个总在会议中出现的问题开始" : "一次有用的對話，可以從一個重複任務、一個不清楚的風險，或一個總在會議中出現的問題開始"}</p><div className="contact-details"><div><span>{lang === "en" ? "Email" : "Email"}</span><a href="mailto:hello@eryndex.example">hello@eryndex.example</a></div><div><span>{lang === "en" ? "Office hours" : lang === "zh-CN" ? "办公时间" : "辦公時間"}</span><p>Mon–Fri / 09:30–18:30<br />Taipei time (GMT+8)</p></div></div></div><div className="contact-form-wrap">{submitted ? <div className="form-success"><div className="success-icon"><CircleCheck size={28} /></div><Eyebrow>{lang === "en" ? "Message received" : lang === "zh-CN" ? "已收到讯息" : "已收到訊息"}</Eyebrow><h2>{lang === "en" ? "Thank you. We will bring the right questions" : lang === "zh-CN" ? "谢谢，我们会带着合适的问题回来" : "謝謝，我們會帶著合適的問題回來"}</h2><p>{lang === "en" ? "This is a demo form, so no message was sent to a CRM. The success state is here to show the intended experience" : lang === "zh-CN" ? "这是一个示范表单，因此没有将讯息送往 CRM此成功状态用于展示预期的互动体验" : "這是一個示範表單，因此沒有將訊息送往 CRM此成功狀態用來展示預期的互動體驗"}</p><button className="button button-secondary" onClick={() => { setSubmitted(false); setErrors({}); }}>{lang === "en" ? "Send another message" : lang === "zh-CN" ? "再发送一则讯息" : "再送出一則訊息"}</button></div> : <form className="contact-form" onSubmit={handleSubmit} noValidate><div className="form-heading"><h2>{lang === "en" ? "Tell us where to look" : lang === "zh-CN" ? "告诉我们从哪里开始" : "告訴我們從哪裡開始"}</h2></div><div className="form-row"><label>{tx(labels.name, lang)}<input name="name" type="text" autoComplete="name" aria-invalid={Boolean(errors.name)} />{errors.name && <small>{errors.name}</small>}</label><label>{tx(labels.company, lang)}<input name="company" type="text" autoComplete="organization" aria-invalid={Boolean(errors.company)} />{errors.company && <small>{errors.company}</small>}</label></div><label>{tx(labels.email, lang)}<input name="email" type="email" autoComplete="email" placeholder="name@company.com" aria-invalid={Boolean(errors.email)} />{errors.email && <small>{errors.email}</small>}</label><label>{tx(labels.need, lang)}<select name="need" defaultValue=""><option value="" disabled>{lang === "en" ? "Select one" : lang === "zh-CN" ? "请选择" : "請選擇"}</option><option value="automation">{lang === "en" ? "Workflow automation" : lang === "zh-CN" ? "工作流自动化" : "工作流程自動化"}</option><option value="security">{lang === "en" ? "Security and access" : lang === "zh-CN" ? "资安与权限" : "資安與權限"}</option><option value="insight">{lang === "en" ? "Operational intelligence" : lang === "zh-CN" ? "运营洞察" : "營運洞察"}</option><option value="edge">{lang === "en" ? "On-site AI" : lang === "zh-CN" ? "内部 AI" : "內部 AI"}</option></select>{errors.need && <small>{errors.need}</small>}</label><label>{tx(labels.message, lang)}<textarea name="message" rows={5} aria-invalid={Boolean(errors.message)} placeholder={lang === "en" ? "A workflow, a question, or a constraint..." : lang === "zh-CN" ? "一个工作流、一个问题，或一个限制条件……" : "一個工作流程、一個問題，或一個限制條件……"} />{errors.message && <small>{errors.message}</small>}</label><div className="form-submit-row"><p>{lang === "en" ? "Demo content only. No CRM connection is made" : lang === "zh-CN" ? "示范内容不会连接 CRM" : "示範內容不會連接 CRM"}</p><button className="button button-primary" type="submit">{lang === "en" ? "Request a demo" : lang === "zh-CN" ? "预约产品演示" : "預約產品展示"}<ArrowUpRight size={16} /></button></div></form>}</div></div></section></>;
}

